INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-01','Fourier Series: Square Wave Harmonics','Easy','ECE','arena','predict','Signals & Systems','multiple_choice','A periodic square wave with frequency f₀ contains which frequency components in its Fourier series?','{"choices": ["Only f₀ and 2f₀", "All harmonics: f₀, 2f₀, 3f₀, ...", "f₀ and all odd harmonics: f₀, 3f₀, 5f₀, 7f₀, ...", "Only the fundamental f₀"], "correct": 2}'::jsonb,'A symmetric square wave (50% duty) has only odd harmonics: f₀, 3f₀, 5f₀... with amplitudes 1, 1/3, 1/5... The even harmonics cancel due to half-wave symmetry. Gibbs phenomenon: finite sum shows 9% overshoot at discontinuities.','{multiple_choice}'::text[],0.82) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-02','Convolution and LTI Systems','Easy','ECE','arena','interpret','Signals & Systems','multiple_choice','For an LTI (Linear Time-Invariant) system, the output y(t) for any input x(t) is:','{"choices": ["y(t) = x(t) × h(t) (multiplication)", "y(t) = x(t) + h(t) (addition)", "y(t) = x(t) * h(t) (convolution with impulse response h(t))", "y(t) = x(t) / h(t)"], "correct": 2}'::jsonb,'For any LTI system, knowing the impulse response h(t) completely characterises the system: y(t) = x(t) * h(t) = ∫x(τ)h(t−τ)dτ. In frequency domain: Y(ω) = X(ω) × H(ω) — multiplication replaces convolution.','{multiple_choice}'::text[],0.85) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-03','Z-Transform Region of Convergence','Easy','ECE','arena','interpret','Signals & Systems','multiple_choice','The Z-transform of a causal discrete-time sequence x[n]u[n] (right-sided signal) converges for:','{"choices": ["|z| < 1", "|z| > r (outside a circle of radius r in the z-plane)", "All z", "|z| = 1 only"], "correct": 1}'::jsonb,'Right-sided (causal) sequences: ROC is |z| > r (outside some circle). Left-sided: |z| < r. Two-sided: annular region. For stable causal systems: ROC must include the unit circle |z| = 1. The ROC distinguishes between different sequences with the same rational Z-transform.','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-04','Energy vs Power Signals','Easy','ECE','arena','classify','Signals & Systems','multiple_choice','A sinusoidal signal sin(2πt) is:','{"choices": ["An energy signal (finite total energy)", "Both energy and power signal", "Neither energy nor power signal", "A power signal (finite average power, infinite total energy)"], "correct": 3}'::jsonb,'Energy signal: E = ∫|x(t)|² dt < ∞. Power signal: P = lim(T→∞) (1/2T) ∫|x(t)|² dt < ∞ and finite. sin(2πt): extends forever → infinite energy. Average power = 1/2 (finite). Therefore it is a power signal.','{multiple_choice}'::text[],0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-05','Sampling Theorem: Aliasing','Easy','ECE','arena','predict','Signals & Systems','multiple_choice','A 1 kHz sinusoidal signal is sampled at 1.5 kHz (below Nyquist rate of 2 kHz). The apparent frequency after sampling (alias frequency) is:','{"choices": ["1 kHz (unchanged)", "0.5 kHz (500 Hz)", "2 kHz", "1.5 kHz"], "correct": 1}'::jsonb,'Alias frequency = |f_signal − f_sample| = |1000 − 1500| = 500 Hz. The 1 kHz signal "folds" back to 500 Hz. Sampling rate must be > 2 × f_max to avoid aliasing. Anti-aliasing filter (LPF at f_s/2) must precede the sampler.','{multiple_choice}'::text[],0.82) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-06','Transfer Function Poles and Zeros','Medium','ECE','arena','interpret','Signals & Systems','multiple_choice','A system has transfer function H(s) = (s+2) / ((s+1)(s+3)). The poles are at:','{"choices": ["s = −2", "s = −1 and s = −3", "s = +1 and s = +3", "s = −2 and 0"], "correct": 1}'::jsonb,'Poles: values of s where H(s) → ∞ = roots of denominator = s+1=0 → s=−1, s+3=0 → s=−3. Zero: root of numerator = s=−2. Poles in left half-plane (negative real part) → stable system.','{multiple_choice}'::text[],0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-07','Bode Plot: First-Order Low-Pass System','Medium','ECE','arena','predict','Signals & Systems','multiple_choice','A first-order LPF with cutoff ω_c = 100 rad/s has gain of 0 dB at DC. At ω = 100 rad/s, the gain is −3 dB and phase is −45°. At ω = 1000 rad/s (one decade above), the approximate gain is:','{"choices": ["−10 dB", "−20 dB", "−40 dB", "−3 dB"], "correct": 1}'::jsonb,'First-order LPF asymptotic Bode: above ω_c, rolls off at −20 dB/decade. One decade above ω_c: gain ≈ −3 − 20 = −23 dB → approximately −20 dB (using asymptotic, not exact). Exact: 20log(1/√(1+(10)²)) = 20log(0.0995) ≈ −20 dB.','{multiple_choice}'::text[],0.76) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-08','Discrete Fourier Transform: Frequency Resolution','Medium','ECE','arena','calculate','Signals & Systems','multiple_choice','A DFT is computed on N = 1024 samples taken at f_s = 8 kHz. The frequency resolution (spacing between DFT bins) is:','{"choices": ["8 Hz", "7.8125 Hz", "1 Hz", "8 kHz"], "correct": 1}'::jsonb,'Frequency resolution Δf = f_s / N = 8000 / 1024 = 7.8125 Hz. To improve resolution: increase N (longer observation window) while keeping f_s constant. DFT resolution is inversely proportional to observation time.','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-09','BIBO Stability Condition','Medium','ECE','arena','interpret','Signals & Systems','multiple_choice','An LTI system is BIBO (Bounded-Input Bounded-Output) stable if and only if its impulse response h(t) satisfies:','{"choices": ["h(t) is causal", "∫|h(t)|dt < ∞ — the impulse response is absolutely integrable (L1 norm is finite)", "h(t) → 0 as t → ∞", "h(t) is periodic"], "correct": 1}'::jsonb,'BIBO stability: bounded input → bounded output. Condition: ∫|h(t)|dt < ∞. In s-domain: all poles must have negative real parts (left half-plane). If any pole is on or to the right of jω axis, the system is unstable.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-10','FIR vs IIR Filter: Phase Response','Medium','ECE','arena','compare','Signals & Systems','multiple_choice','FIR (Finite Impulse Response) filters are preferred over IIR filters in audio applications requiring linear phase because:','{"choices": ["FIR filters use less computation", "FIR filters with symmetric coefficients have strictly linear phase (constant group delay) — all frequency components are delayed by the same amount, preventing phase distortion", "IIR filters cannot achieve the required frequency selectivity", "FIR filters are always more stable"], "correct": 1}'::jsonb,'Linear phase means group delay τ = −dφ/dω = constant. Symmetric FIR: φ(ω) = −ω(N−1)/2 → linear. IIR filters have nonlinear phase (elliptic filters especially). For data communications and audio: phase distortion matters. Medical signal processing (ECG): linear phase FIR.','{multiple_choice}'::text[],0.7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-11','PSD: Noise Power in Bandwidth','Medium','ECE','arena','calculate','Signals & Systems','multiple_choice','White noise has power spectral density (PSD) S(f) = N₀/2 = 10⁻⁹ W/Hz (two-sided). Noise power in a 1 MHz bandwidth (single-sided):
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-12','Windowing in Spectral Analysis','Medium','ECE','arena','select','Signals & Systems','multiple_choice','Spectral leakage in DFT analysis is reduced by applying a window function before computing the DFT. A Hanning window reduces leakage because:','{"choices": ["It increases the DFT length", "It tapers the signal to zero at both ends, reducing the discontinuity at the observation window boundaries that causes spectral leakage from the rectangular window", "It increases frequency resolution", "It removes DC offset"], "correct": 1}'::jsonb,'Rectangular window: abrupt truncation → spectral leakage (side lobes at −13 dB). Hanning: cosine taper → −31 dB side lobes but wider main lobe (lower frequency resolution). Blackman: −57 dB side lobes. Choose window based on required selectivity vs leakage trade-off.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-13','Correlation: Signal Detection','Hard','ECE','arena','interpret','Signals & Systems','multiple_choice','Cross-correlation R_xy(τ) is used in radar and sonar to:','{"choices": ["Measure signal power", "Find the time delay between a transmitted pulse and its echo — the peak of R_xy(τ) occurs at the time lag equal to the propagation delay, regardless of noise", "Compute signal frequency", "Filter noise from a signal"], "correct": 1}'::jsonb,'R_xy(τ) = ∫x(t)y(t+τ)dt. Peak at τ=τ₀ means y is a delayed version of x by τ₀. In radar: transmit x(t), receive y(t)=x(t−τ)+noise. Correlate → find τ → distance = c×τ/2. Works below noise floor (processing gain = BW × T).','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-14','Parseval''s Theorem','Hard','ECE','arena','interpret','Signals & Systems','multiple_choice','Parseval''s theorem states that for a signal x(t) and its Fourier transform X(f):
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-15','Group Delay and Phase Delay','Hard','ECE','arena','interpret','Signals & Systems','multiple_choice','Group delay τ_g(ω) = −dφ(ω)/dω represents:','{"choices": ["The phase shift at each frequency", "The time delay of the envelope of a narrowband signal passing through the system — if constant, all frequency components are delayed equally (no dispersion)", "The inverse of bandwidth", "Signal propagation speed"], "correct": 1}'::jsonb,'Phase delay τ_p = −φ(ω)/ω: delay of the carrier. Group delay τ_g = −dφ/dω: delay of the envelope (modulation). For linear phase systems: τ_g = constant → no dispersion (all spectral components delayed equally). In dispersive media (optical fibre): different frequencies travel at different speeds.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-16','Matched Filter: SNR Maximisation','Hard','ECE','arena','select','Signals & Systems','multiple_choice','A matched filter is the optimal linear filter for detecting a known signal in AWGN noise because:','{"choices": ["It has the widest bandwidth possible", "Its impulse response is h(t) = s(T−t) (time-reversed and shifted version of the signal) — this maximises the output SNR at the sampling instant, providing optimal signal detection", "It eliminates all noise", "It is the simplest to implement"], "correct": 1}'::jsonb,'Matched filter output at time T: maximum SNR = 2E/N₀ where E is signal energy. The matched filter correlates the received signal with a reference copy — equivalent to cross-correlation. Used in radar, CDMA, and digital communications receivers.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-17','FFT Computational Complexity','Hard','ECE','arena','compare','Signals & Systems','multiple_choice','Computing the DFT directly requires O(N²) operations. The Cooley-Tukey FFT algorithm reduces this to:','{"choices": ["O(N)", "O(N log₂ N)", "O(N²/2)", "O(√N)"], "correct": 1}'::jsonb,'FFT: O(N log₂ N). For N=1024: DFT = 1,048,576 operations; FFT = 10,240 operations — 100× speedup. For N=1M: DFT = 10¹², FFT = 20M — speedup of 50,000×. The FFT uses divide-and-conquer (butterfly structure) exploiting periodicity and symmetry of twiddle factors.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-18','Hilbert Transform and Analytic Signal','Hard','ECE','arena','interpret','Signals & Systems','multiple_choice','The analytic signal z(t) = x(t) + jx̂(t) (where x̂ is the Hilbert transform of x) is used in communications because:','{"choices": ["It doubles the signal bandwidth", "It converts real signals to complex representation — enabling single-sideband (SSB) modulation, instantaneous frequency/amplitude calculation, and efficient quadrature (IQ) processing", "It provides noise immunity", "It compresses signal dynamic range"], "correct": 1}'::jsonb,'Analytic signal: positive frequencies only (one-sided spectrum). Instantaneous amplitude = |z(t)| (envelope). Instantaneous phase = angle(z(t)). Instantaneous frequency = dφ/dt. Used in SSB modulation, IQ demodulation, and Hilbert-phase measurements.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-19','Wiener Filter: Optimal Estimation','Hard','ECE','arena','select','Signals & Systems','multiple_choice','A Wiener filter is an optimal linear filter for estimating a desired signal s(t) from a noisy observation y(t) = s(t) + n(t) when:','{"choices": ["Only when the noise is white", "The power spectral densities of signal and noise are known — the filter minimises mean square error: H(f) = S_sy(f)/S_yy(f)", "The noise is identically zero", "The signal is stationary and Gaussian (then it is also optimal nonlinear)"], "correct": 1}'::jsonb,'Wiener filter: H(f) = S_ss(f)/(S_ss(f) + S_nn(f)) for signal estimation. Where SNR is high (S_ss >> S_nn): H → 1 (pass signal). Where SNR is low: H → 0 (suppress noise). The Kalman filter is the Wiener filter extended to non-stationary signals.','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-20','Discrete-Time System: Difference Equation','Hard','ECE','arena','calculate','Signals & Systems','multiple_choice','A discrete-time system: y[n] = 0.5y[n−1] + x[n]. Input x[n] = δ[n] (unit impulse). y[0] = 1, y[1] = ?','{"choices": ["1", "0.5", "0.25", "0"], "correct": 1}'::jsonb,'y[0] = 0.5y[−1] + x[0] = 0 + 1 = 1 (since y[−1]=0 for causal system). y[1] = 0.5y[0] + x[1] = 0.5×1 + 0 = 0.5. y[n] = 0.5ⁿ u[n] — exponentially decaying impulse response. System is stable (pole at z=0.5, inside unit circle).','{multiple_choice}'::text[],0.7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-21','Wavelet Transform vs STFT','Hard','ECE','arena','compare','Signals & Systems','multiple_choice','Continuous Wavelet Transform (CWT) provides better time-frequency analysis than Short-Time Fourier Transform (STFT) for non-stationary signals because:','{"choices": ["CWT uses a rectangular window like STFT", "CWT window length scales with frequency — high-frequency analysis uses short windows (good time resolution), low-frequency uses long windows (good frequency resolution). STFT uses fixed window size for all frequencies", "CWT is faster to compute", "CWT uses complex exponentials as basis functions"], "correct": 1}'::jsonb,'STFT: fixed window → fixed time-frequency resolution (Heisenberg uncertainty: Δt × Δf = constant). CWT: wavelet scales with frequency → variable resolution. High-f: narrow → precise timing. Low-f: wide → precise frequency. Better suited for speech, seismic, ECG analysis.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-22','Nyquist Plot and Gain Margin','Hard','ECE','arena','interpret','Signals & Systems','multiple_choice','In a Nyquist plot of loop transfer function G(jω)H(jω), the gain margin is determined by:','{"choices": ["The distance of the plot from the origin at ω = 0", "1/|G(jω)H(jω)| evaluated at the frequency where the phase is −180° — the reciprocal of the gain magnitude at the phase crossover frequency", "The area enclosed by the Nyquist curve", "The frequency at which the curve crosses the real axis"], "correct": 1}'::jsonb,'Phase crossover frequency ωₚ: where phase = −180°. Gain margin = 1/|GH(jωₚ)| in linear, or −20log|GH(jωₚ)| in dB. If |GH| < 1 at ωₚ → GM > 0 dB → stable. System is on the verge of instability when the Nyquist curve passes through the (−1, 0) point.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-23','Compressive Sensing','Hard','ECE','arena','interpret','Signals & Systems','multiple_choice','Compressive sensing (compressed sensing) challenges the Nyquist theorem by allowing:','{"choices": ["Signal reconstruction using above-Nyquist sampling", "Accurate reconstruction of sparse signals from far fewer measurements than required by Nyquist — by exploiting signal sparsity in some basis and solving L1-norm minimisation", "Signal compression for storage only", "Elimination of ADC quantisation noise"], "correct": 1}'::jsonb,'CS: if signal has K non-zero components in some basis (K-sparse), M = O(K log N) random measurements (not N Nyquist samples) suffice for reconstruction via L1 minimisation (basis pursuit). Applications: MRI (fewer scans), radar, single-pixel camera, compressive spectroscopy.','{multiple_choice}'::text[],0.5) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-24','Adaptive Filtering: LMS Algorithm','Hard','ECE','arena','interpret','Signals & Systems','multiple_choice','The LMS (Least Mean Squares) adaptive filter is used in noise cancellation because:','{"choices": ["It requires knowledge of the noise power spectrum", "It iteratively adjusts filter coefficients to minimise mean squared error — using a reference noise input, it adapts in real time to cancel correlated noise from the primary signal even as noise characteristics change", "It is a fixed FIR filter", "It requires a training sequence always"], "correct": 1}'::jsonb,'LMS: w[n+1] = w[n] + µ × e[n] × x[n]. e[n] = d[n] − y[n] is the error signal. µ controls convergence speed vs stability. Used in: echo cancellation (phone), noise-cancelling headphones (Bose/Sony), adaptive equalisation. Computationally simple: O(N) per sample.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ss-25','Power Spectral Density: Ergodicity','Hard','ECE','arena','interpret','Signals & Systems','multiple_choice','A random process is ergodic (in the mean) if:','{"choices": ["All sample functions are identical", "Time averages equal ensemble averages — a single long realisation contains sufficient statistical information to represent the entire process", "The process is Gaussian", "The autocorrelation is zero for all non-zero lags"], "correct": 1}'::jsonb,'Ergodicity: time average of one realisation = ensemble average across all realisations. Ergodic processes allow PSD estimation from a single time record (Welch method, periodogram). Most real stationary processes are assumed ergodic in practice.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
